const T=[
 {id:"literatura",ic:"🎨",col:"#4338ca",titol:"La literatura: l'art de la paraula",font:"Llibre · Literatura 1.1 · pàg. 42",
  idea:"La literatura és l'art de dir coses de manera creativa, amb un llenguatge estètic (bonic), per emocionar i agradar.",
  pts:["<b>Literatura</b> = l'<b>art de dir</b> coses de manera <b>creativa</b> per mitjà d'un <b>llenguatge estètic</b>.",
   "Busca la <b>bellesa</b> de les paraules per comunicar <b>fets, sentiments i imatges</b>.",
   "L'objectiu és <b>emocionar</b> i <b>agradar</b>.",
   "Exemple del llibre: <b>Maria Dolors Alibés</b> (<i>Contes per a l'hora de les postres</i>) no diu «els records fan mal». Diu que són com <b>roses</b> oloroses, suaus, però amb <b>espines</b> que s'enganxen a la pell.",
   "Pot parlar de coses ben <b>reals</b>, com un vespre de tardor o un olivar. El que la fa literatura és <b>com</b> ho diu.",
   "💡 <i>Sabies que…?</i> <i>Literatura</i> ve del llatí <i>littera</i>, que vol dir «lletra»."],
  truc:"<b>Literatura = dir-ho bonic.</b> No compta tant <b>què</b> dius, sinó <b>com</b> ho dius.",
  compte:"La literatura <b>no</b> és «l'art de fer imaginar coses que no existeixen». Pot parlar de coses reals: el que compta és que ho diu de manera creativa.",
  fc:[["Què és la literatura?","L'art de dir coses de manera creativa, amb un llenguatge estètic."],["Què busca la literatura en les paraules?","La bellesa, per comunicar fets, sentiments i imatges."],["Quin és l'objectiu de la literatura?","Emocionar i agradar."],["La literatura només parla de coses inventades?","No. Pot parlar de coses reals: el que compta és com ho diu."],["Amb què compara els records Maria Dolors Alibés?","Amb roses: suaus, però amb espines que s'enganxen a la pell."]],
  q:[["Què és la literatura?",["L'art de dir coses de manera creativa, amb un llenguatge estètic","L'art de fer imaginar coses que no existeixen","Qualsevol text que estigui escrit en un llibre, encara que sigui de mates"],0,"És l'art de la paraula: dir les coses de manera creativa i bonica."],
     ["Quin és l'objectiu de la literatura?",["Donar dades exactes","Emocionar i agradar","Donar instruccions"],1,"La literatura vol emocionar i agradar."],
     ["Un poema parla d'un olivar que existeix de veritat. Pot ser literatura?",["No, perquè parla d'una cosa real","Només si l'olivar és inventat","Sí, si ho diu de manera creativa"],2,"La literatura pot parlar de coses reals. El que compta és com ho diu."],
     ["Què fa que un text sigui literatura?",["Que expliqui coses que no han passat mai","Com ho diu: de manera creativa i artística","Que sigui molt llarg i tingui capítols"],1,"No compta tant què dius, sinó com ho dius."],
     ["Quina d'aquestes frases és més literària?",["Fa molt de fred","Avui fa zero graus","El fred em mossega les orelles"],2,"Diu el mateix, però amb una imatge creativa."],
     ["Què fa Maria Dolors Alibés per parlar dels bons records?",["Els compara amb roses que punxen","Diu, sense més, que de vegades fan mal","Fa una llista dels seus records"],0,"No diu «fan mal»: diu que són roses amb espines. Això és literatura."],
     ["Què comunica la literatura amb les paraules?",["Només dades i xifres","Fets, sentiments i imatges","Només històries d'herois"],1,"Busca la bellesa de les paraules per comunicar fets, sentiments i imatges."],
     ["La literatura és l'art de…",["la pintura","la paraula","la música"],1,"Fa art amb les paraules."]]},
 {id:"oral",ic:"🔥",col:"#ea580c",titol:"La literatura oral tradicional",font:"Llibre · Literatura 1.2 · pàg. 42",
  idea:"Les primeres obres literàries van ser orals: es transmetien de viva veu, de pares a fills i a néts, molt abans que existís l'escriptura.",
  pts:["Les <b>primeres manifestacions literàries</b> van ser <b>orals</b> i són molt anteriors a l'escriptura.",
   "Els primers humans ja <b>cantaven cançons</b> i <b>s'explicaven històries</b>. Per fer-les més emocionants, feien servir l'art de la literatura.",
   "Així van néixer els primers <b>textos literaris no escrits</b>.",
   "Es van conservar a la <b>memòria</b>: els pares els transmetien als fills, i els fills, als néts.",
   "Amb el temps s'ha format un ric <b>patrimoni cultural</b>: la <b>literatura oral tradicional</b>.",
   "Exemple del llibre (activitat 11): la narració oral dels <b>indis oglales</b>, la de la roca que parla amb el Gran Esperit.",
   "💡 <i>Sabies que…?</i> La <i>Ilíada</i> i l'<i>Odissea</i> es van explicar de viva veu durant segles abans que algú les escrivís."],
  truc:"<b>Pare → fill → nét.</b> La literatura oral és una herència que es passa de boca en boca i no ocupa lloc.",
  compte:"Les primeres obres literàries <b>no</b> van ser escrites: eren <b>orals</b>, molt anteriors a l'escriptura.",
  fc:[["Com van ser les primeres obres literàries?","Orals: es transmetien de viva veu."],["On es conservaven els textos quan no hi havia escriptura?","A la memòria."],["Com es transmetia la literatura oral?","De pares a fills, i dels fills als néts."],["Per què els primers humans feien servir la literatura?","Per fer més emocionants les cançons i les històries."],["Com es diu aquest patrimoni de cançons i històries?","La literatura oral tradicional."]],
  q:[["Com van ser les primeres obres literàries?",["Escrites a mà pels copistes","Orals, de viva veu","Impreses en llibres"],1,"Es transmetien de viva veu, molt abans de l'escriptura."],
     ["On es guardaven els textos literaris quan encara no hi havia escriptura?",["A la memòria de les persones","En llibres manuscrits","A les biblioteques"],0,"Es conservaven a la memòria i passaven de pares a fills."],
     ["Com es transmetia la literatura oral?",["Per carta, d'un poble a un altre","De pares a fills, i dels fills als néts","Copiant-la en pergamins"],1,"Pare → fill → nét."],
     ["Per què els primers humans feien servir la literatura quan cantaven i explicaven històries?",["Per fer-les més emocionants","Per poder-les escriure","Per guardar-les en un llibre"],0,"L'art de la literatura feia les històries més emocionants."],
     ["Les primeres manifestacions literàries són…",["posteriors a la impremta","de la mateixa època que l'escriptura","molt anteriors a l'escriptura"],2,"Primer es deien; molt més tard es van escriure."],
     ["Què és la literatura oral tradicional?",["Les cançons i històries que es transmeten de viva veu","Les obres que llegim sols i en silenci, en un llibre imprès","Els llibres que copiaven els copistes"],0,"És un patrimoni cultural que passa de boca en boca."],
     ["Quin exemple de literatura oral surt a l'activitat 11 del llibre?",["Julieta i el verí","La roca que parla dels indis oglales","El comte de Mataplana"],1,"És una narració oral dels indis oglales."],
     ["Com eren els primers textos literaris?",["Textos no escrits","Textos escrits en vers","Textos d'un autor conegut"],0,"Van néixer abans de l'escriptura: eren textos no escrits."]]},
 {id:"escrita",ic:"✍️",col:"#b45309",titol:"La literatura escrita",font:"Llibre · Literatura 1.3 · pàg. 42-43",
  idea:"L'invent de l'alfabet va portar l'escriptura: el text va quedar fixat, l'obra va tenir un autor amb nom i la lectura es va tornar solitària i silenciosa.",
  pts:["La <b>invenció de l'alfabet</b> va impulsar un nou procediment per crear literatura: l'<b>escriptura</b>.",
   "L'<b>escriptor solitari i reflexiu</b> va anar <b>arraconant</b> l'artista popular que recitava de viva veu.",
   "La <b>persona solitària i silenciosa</b> amb un llibre a les mans va anar <b>relegant</b> el grup d'oients.",
   "<b>Com es transmet</b>: l'oral, de paraula (un <b>orador</b> recitava i el públic escoltava). L'escrita, per escrit: abans de la <b>impremta</b>, els llibres eren <b>manuscrits</b> i els <b>copistes</b> en feien les còpies.",
   "<b>Qui n'és l'autor</b>: l'oral és <b>anònima</b> (no en sabem l'autor, és patrimoni popular). L'escrita és <b>d'autor</b>, amb el nom a la portada.",
   "<b>Com és el text</b>: l'oral té <b>diverses versions</b> (cada orador l'adapta al seu públic). L'escrita té una <b>versió única</b>, invariable.",
   "💡 <i>Sabies que…?</i> Gutenberg va posar en marxa la impremta cap al 1450. Abans, un copista podia passar mesos copiant un sol llibre."],
  truc:"L'<b>oral</b> és com el joc del <b>telèfon espatllat</b>: passa de boca en boca i cadascú la canvia una mica. L'<b>escrita</b> és com una <b>foto</b>: queda quieta (versió única) i porta la firma (d'autor).",
  compte:"<b>Anònima</b> vol dir que <b>no sabem qui</b> la va fer, no que la van fer molts autors junts. I l'escriptura <b>no</b> va amagar els autors: va fer que el text quedés fixat i que l'obra tingués un autor amb nom.",
  fc:[["Què va portar la invenció de l'alfabet?","L'escriptura, un nou procediment per crear literatura."],["Què vol dir «anònima»?","Que no sabem qui l'ha feta."],["Qui era un copista?","La persona que copiava els llibres a mà, abans de la impremta."],["Quantes versions té una obra escrita?","Una de sola: el text queda invariable."],["Per què l'oral té diverses versions?","Perquè cada orador l'adapta als gustos del seu públic."],["Qui va quedar arraconat amb l'escriptura?","L'artista que recitava de viva veu i el grup que l'escoltava."]],
  q:[["Què va provocar la invenció de l'alfabet?",["Que les obres quedessin en l'anonimat","L'escriptura: el text quedava fixat i l'obra tenia autor","Que cada orador canviés la història al seu gust"],1,"Amb l'escriptura, versió única i d'autor."],
     ["Què vol dir que una obra és anònima?",["Que la van fer molts autors junts","Que no sabem qui la va fer","Que és molt antiga i ja no s'explica"],1,"Anònima = d'autor desconegut."],
     ["Com es transmetia la literatura escrita abans de la impremta?",["En llibres manuscrits copiats pels copistes","De viva veu: un orador recitava i el públic l'escoltava","En llibres impresos a la impremta"],0,"Abans de la impremta, els copistes copiaven els llibres a mà."],
     ["Quantes versions té el text d'una obra de literatura oral?",["Una de sola, invariable","Diverses, perquè cada orador l'adapta","Només dues: la del pare i la del fill"],1,"L'oral canvia una mica cada vegada que s'explica."],
     ["Quina característica és de la literatura escrita?",["És anònima","Té diverses versions","Té un autor concret"],2,"L'escrita és d'autor: el seu nom surt a la portada."],
     ["Qui va anar arraconant l'escriptor solitari i reflexiu?",["L'artista popular que recitava de viva veu","Els copistes que copiaven a mà","Els lectors silenciosos"],0,"L'escriptor sol a la taula va prendre el lloc de l'artista que recitava."],
     ["Amb l'escriptura, com es va tornar la lectura?",["Cantada en grup, al voltant d'un foc","Solitària i silenciosa","Sempre en veu alta davant del públic"],1,"Una persona sola amb un llibre va relegar el grup d'oients."],
     ["Quina d'aquestes frases és de la literatura oral tradicional?",["Té el nom de l'autor a la portada","El text es manté sempre igual","És patrimoni popular"],2,"L'oral és anònima: és de tothom, patrimoni popular."],
     ["Qui era el copista?",["La persona que copiava els llibres a mà","L'orador que recitava davant del públic","L'autor que inventava les històries"],0,"Feia les còpies dels llibres manuscrits."]]},
 {id:"generes",ic:"📚",col:"#7c3aed",titol:"Els gèneres literaris: vers i prosa",font:"Llibre · Literatura 1.4 · pàg. 44",
  idea:"Segons la forma i el contingut, les obres literàries es classifiquen en quatre grans gèneres: la poesia, la narrativa, el teatre i l'assaig.",
  pts:["Pensa en una biblioteca amb <b>quatre prestatgeries</b>: <b>poesia</b>, <b>narrativa</b>, <b>teatre</b> i <b>assaig</b>. Cada obra va a la seva segons <b>com està escrita</b> (la forma) i <b>de què parla</b> (el contingut).",
   "<b>Textos en vers</b>: segueixen <b>regles mètriques</b>: estrofes, un nombre regular de síl·labes, ritme i, sovint, rima. Cada <b>vers</b> va en una ratlla, i un grup de versos és una <b>estrofa</b>.",
   "<b>Textos en prosa</b>: fan servir la <b>forma habitual</b> del llenguatge, sense regles mètriques. Les línies arriben fins al final de la ratlla.",
   "<b>Poesia</b> (en vers): expressa sentiments, reflexions o fets. <b>Lírica</b>: el poeta expressa un sentiment intens o una reflexió profunda. <b>Èpica</b>: el poeta narra una història llegendària o fantàstica d'uns herois excepcionals.",
   "<b>Narrativa</b> (en prosa): un <b>narrador</b> explica uns fets reals, imaginaris o fantàstics. <b>Curta</b>: història breu i personatges senzills. <b>Llarga</b>: història llarga i personatges complexos.",
   "<b>Teatre</b> (en diàlegs) i <b>assaig</b> (en prosa): els trobaràs al tema següent."],
  truc:"La literatura <b>PiNTA</b> amb paraules: <b>P</b>oesia, <b>N</b>arrativa, <b>T</b>eatre, <b>A</b>ssaig.",
  compte:"La <b>lírica</b> expressa un <b>sentiment</b>; l'<b>èpica</b> explica la història d'uns <b>herois</b>. Totes dues són poesia, en vers.",
  fc:[["Quins són els quatre gèneres literaris?","Poesia, narrativa, teatre i assaig."],["Què és un vers?","Cada ratlla d'un poema."],["Què és una estrofa?","Un grup de versos."],["Què és la prosa?","La forma habitual del llenguatge, sense regles mètriques."],["Lírica o èpica: un poema sobre la gesta d'un heroi","Èpica."],["Narrativa curta o llarga: personatges complexos","Llarga."]],
  q:[["Quins són els quatre grans gèneres literaris?",["Poesia, narrativa, teatre i assaig","Lírica, èpica, tragèdia i comèdia","Conte, novel·la, poema i diàleg"],0,"Recorda: la literatura PiNTA."],
     ["Com s'escriu la poesia?",["En prosa","En vers","En diàlegs"],1,"La poesia va en vers, amb regles mètriques."],
     ["Què són les regles mètriques?",["Estrofes, síl·labes comptades, ritme i, sovint, rima","Les normes per saber on van els punts, les comes i les majúscules","Les parts d'una obra de teatre"],0,"Són les regles que segueixen els textos en vers."],
     ["Què és una estrofa?",["Cada ratlla d'un poema","Un grup de versos","Un poema molt llarg"],1,"Cada ratlla és un vers; un grup de versos és una estrofa."],
     ["Com és la prosa?",["Segueix regles mètriques: estrofes, síl·labes comptades i rima","És la forma habitual del llenguatge, sense regles mètriques","S'escriu sempre amb diàlegs"],1,"Les línies arriben fins al final de la ratlla."],
     ["El poeta expressa un sentiment intens o una reflexió profunda. Quin subgènere és?",["Èpica","Lírica","Narrativa curta"],1,"Lírica = sentiment."],
     ["Un poema narra la història llegendària d'uns herois excepcionals. Quin subgènere és?",["Lírica","Assaig","Èpica"],2,"Èpica = herois i gestes."],
     ["Una novel·la amb una història llarga i personatges complexos és…",["narrativa llarga","narrativa curta","poesia èpica"],0,"La curta té una història breu i personatges senzills."],
     ["Qui explica els fets en una obra narrativa?",["Els personatges, amb diàlegs","Un narrador","L'autor, amb les seves opinions"],1,"A la narrativa hi ha un narrador que explica els fets."]]},
 {id:"teatre",ic:"🎭",col:"#be185d",titol:"El teatre, l'assaig i com reconèixer els gèneres",font:"Llibre · Literatura 1.4 · pàg. 44-45 (activitat 13)",
  idea:"El teatre exposa un conflicte humà amb els diàlegs dels personatges, per representar-lo; l'assaig exposa les reflexions i opinions de l'autor.",
  pts:["<b>Teatre</b> (en <b>diàlegs</b>): exposa un <b>conflicte humà</b> a través dels diàlegs dels personatges, perquè <b>actors i actrius</b> l'interpretin dalt d'un <b>escenari</b>.",
   "<b>Tragèdia</b>: to seriós i greu; desenllaç <b>fatal</b>.",
   "<b>Comèdia</b>: element graciós i burlesc; desenllaç <b>feliç</b>.",
   "<b>Drama</b>: element realista; desenllaç <b>incert</b>.",
   "<b>Desenllaç</b> = com acaba el conflicte d'una obra (com el final d'una pel·li).",
   "<b>Assaig</b> (en <b>prosa</b>): l'autor exposa les seves <b>reflexions i opinions</b> sobre un tema, amb voluntat de creació literària.",
   "Activitat 13: Kent Haruf (la noia que surt del cafè) → <b>narrativa</b> · Verdaguer (el comte de Mataplana i els dos cavalls) → <b>poesia èpica</b> · Josep Pla (l'olivar i la vinya) → <b>assaig</b> · Cèlia Viñas (el mar i el mariner) → <b>poesia lírica</b> · Shakespeare (Julieta i el verí) → <b>tragèdia</b> · Benet i Jornet (l'intendent i el marxant) → <b>comèdia</b>."],
  truc:"Al teatre, la primera lletra et diu el final: <b>T</b>ragèdia = <b>T</b>omba (fatal) · <b>C</b>omèdia = <b>C</b>elebració (feliç) · <b>D</b>rama = <b>D</b>ubte (incert).",
  compte:"La tragèdia i el drama s'assemblen, perquè tots dos són seriosos. Però la <b>tragèdia</b> acaba malament segur i el <b>drama</b> acaba a l'aire.",
  fc:[["Com s'escriu el teatre?","Amb els diàlegs dels personatges."],["Com acaba una tragèdia?","Amb un desenllaç fatal."],["Com acaba una comèdia?","Amb un desenllaç feliç."],["Com acaba un drama?","Amb un desenllaç incert."],["Què fa l'autor en un assaig?","Exposa les seves reflexions i opinions sobre un tema."],["Què és el desenllaç?","Com acaba el conflicte d'una obra."]],
  q:[["Una obra de teatre graciosa i burlesca, amb un desenllaç feliç, és…",["una tragèdia","una comèdia","un drama"],1,"Comèdia = Celebració."],
     ["Com acaba un drama?",["Amb un desenllaç fatal","Amb un desenllaç feliç","Amb un desenllaç incert"],2,"Drama = Dubte: acaba a l'aire."],
     ["Què exposa el teatre a través dels diàlegs dels personatges?",["Un conflicte humà","Les opinions de l'autor","Un sentiment intens del poeta"],0,"Un conflicte humà, per representar dalt d'un escenari."],
     ["En un assaig, l'autor…",["explica una història d'herois","exposa les seves reflexions i opinions","fa parlar els personatges"],1,"L'assaig va en prosa i dona l'opinió de l'autor."],
     ["Josep Pla parla de l'olivar i la vinya i hi diu què en pensa. Quin gènere és?",["Narrativa","Assaig","Poesia lírica"],1,"Reflexions i opinions de l'autor = assaig."],
     ["A l'obra de Shakespeare, Julieta es pren el verí i l'obra acaba malament. Quin subgènere és?",["Drama","Comèdia","Tragèdia"],2,"Desenllaç fatal = tragèdia."],
     ["Verdaguer explica en vers les aventures del comte de Mataplana i els dos cavalls. Quin gènere és?",["Poesia èpica","Narrativa curta","Poesia lírica"],0,"En vers i amb un heroi: poesia èpica."],
     ["Un text amb el nom de cada personatge davant de les seves paraules és…",["teatre","poesia lírica","narrativa"],0,"Els diàlegs dels personatges són la marca del teatre."],
     ["Què és el desenllaç d'una obra?",["El títol de l'obra","Com acaba el conflicte","La primera escena"],1,"El desenllaç és el final del conflicte."],
     ["Quina diferència hi ha entre la tragèdia i el drama?",["La tragèdia acaba malament segur; el drama, a l'aire","La tragèdia fa riure i el drama no","El drama s'escriu en vers i la tragèdia, en prosa i sense diàlegs"],0,"Tots dos són seriosos, però només la tragèdia té un final fatal segur."]]},
 {id:"nom",ic:"🧩",col:"#16a34a",titol:"El nom i el sintagma nominal",font:"Llibre · Gramàtica 1.1 · pàg. 46",
  idea:"El nom anomena persones, animals, plantes, objectes i idees; canvia de gènere i de nombre, i és el nucli (el cor) del sintagma nominal.",
  pts:["Un <b>nom</b> designa una <b>persona</b> (<i>Harry</i>), un <b>animal</b> (<i>mussol</i>), una <b>planta</b> (<i>menta</i>), un <b>objecte</b> (<i>carta</i>) o una <b>idea</b> (<i>amistat</i>).",
   "És una paraula <b>variable</b>: canvia de <b>gènere</b> (masculí / femení) i de <b>nombre</b> (singular / plural): <i>noi, noia, nois, noies</i>.",
   "És el <b>nucli</b> del <b>sintagma nominal (SN)</b>, el grup de paraules que va amb un nom.",
   "L'<b>especificador</b> va davant i presenta el nom (<i>un, quatre, els teus</i>). El <b>complement</b> va darrere i hi afegeix detalls (<i>groguenc, de màgia</i>).",
   "<i>un</i> (especificador) · <b>sobre</b> (nucli) · <i>groguenc</i> (complement).",
   "Activitat 14 (el nucli, en negreta): un <b>bruixot</b> molt bo · quatre <b>trucs</b> de màgia · els teus <b>ulls</b> verds i ametllats · una <b>pregunta</b> difícil de respondre.",
   "💡 <i>Sabies que…?</i> El nom també es diu <b>substantiu</b>."],
  truc:"El SN és un trencaclosques de tres peces: <b>el que presenta</b> (especificador), <b>el protagonista</b> (nucli) i <b>el que dona detalls</b> (complement). Per trobar el nucli, pregunta't: quina paraula, si la trec, ja no sé de què parlo?",
  compte:"L'especificador i el complement poden tenir <b>més d'una paraula</b> (<i>els teus</i>, <i>difícil de respondre</i>). El nucli és sempre <b>un sol nom</b>.",
  fc:[["Què pot designar un nom?","Persones, animals, plantes, objectes i idees."],["Per què diem que el nom és variable?","Perquè canvia de gènere i de nombre."],["Quines són les tres peces del sintagma nominal?","Especificador, nucli i complement."],["Quin és el nucli de «un sobre groguenc»?","Sobre."],["On va l'especificador?","Davant del nom: el presenta."],["On va el complement?","Darrere del nom: hi afegeix detalls."]],
  q:[["Quina d'aquestes paraules és un nom que designa una idea?",["amistat","mussol","carta"],0,"Mussol és un animal i carta, un objecte."],
     ["Per què diem que el nom és una paraula variable?",["Perquè sempre va davant del verb","Perquè canvia de gènere i de nombre","Perquè es pot escriure amb majúscula"],1,"noi, noia, nois, noies."],
     ["Quin és el nucli de «els teus ulls verds i ametllats»?",["els teus","ulls","verds"],1,"Si treus «ulls», ja no saps de què parles."],
     ["A «un sobre groguenc», què és «groguenc»?",["L'especificador","El nucli","El complement"],2,"Va darrere del nom i hi afegeix un detall."],
     ["Què fa l'especificador?",["Va davant del nom i el presenta","Va darrere del nom i hi afegeix detalls","És el nom principal del grup"],0,"un, quatre, els teus…"],
     ["Quantes paraules té el nucli d'un sintagma nominal?",["Un sol nom","Dues paraules com a mínim","Tantes com vulguis"],0,"L'especificador i el complement poden ser llargs; el nucli és un sol nom."],
     ["Quin és el nucli de «una pregunta difícil de respondre»?",["difícil","pregunta","respondre"],1,"«difícil de respondre» és el complement."],
     ["A «quatre trucs de màgia», què és «de màgia»?",["El complement","L'especificador","El nucli"],0,"Va darrere i diu quina mena de trucs."],
     ["Quin truc serveix per trobar el nucli?",["Buscar sempre la primera paraula del grup, la que el presenta","Pensar quina paraula, si la trec, ja no sé de què parlo","Buscar la paraula més llarga"],1,"El nucli és el protagonista: sense ell, no se sap de què parles."]]},
 {id:"classes",ic:"🗂️",col:"#0d9488",titol:"Les classes de noms",font:"Llibre · Gramàtica 1.2 · pàg. 46-47",
  idea:"Segons el que designen, els noms es classifiquen en quatre parelles: comuns i propis, concrets i abstractes, individuals i col·lectius, comptables i no comptables.",
  pts:["<b>Comuns</b>: qualsevol element d'una mateixa classe (<i>noia, illa, ciutat</i>). <b>Propis</b>: un element únic: noms de persona o <b>antropònims</b> (<i>Paula</i>) i noms de lloc o <b>topònims</b> (<i>Menorca, Maó</i>).",
   "<b>Concrets</b>: una persona, un animal o una cosa material (<i>pescador, gat, rosa</i>). <b>Abstractes</b>: realitats no materials: conceptes, qualitats o estats (<i>veritat, valentia, calma</i>).",
   "<b>Individuals</b>: en singular, designen un sol element (<i>persona, alumne, ovella</i>). <b>Col·lectius</b>: en singular, designen un conjunt (<i>gent, alumnat, ramat</i>).",
   "<b>Comptables</b>: es compten per unitats i admeten un numeral (<i>dos pastissos, tres roses</i>). <b>No comptables</b>: no es compten; admeten <b>quantitatius</b> i <b>noms de mesura</b> (<i>poca farina, un quilo de sal, un raig d'oli</i>).",
   "Un nom porta les quatre etiquetes alhora: <i>ramat</i> = comú + concret + col·lectiu + comptable.",
   "Activitats 16 i 17: pi → <b>pineda</b>, flor → <b>ram</b>, jugador → <b>equip</b>, ocell → <b>aviram</b> · una <b>cullerada</b> de melmelada, un <b>got</b> de llet, un <b>rajolí</b> d'oli, un <b>pessic</b> de sal."],
  truc:"Quatre preguntes per a cada nom: <b>Té nom de pila o de mapa?</b> (propi) · <b>El puc tocar?</b> (concret) · <b>És un o són molts?</b> (col·lectiu) · <b>Hi puc posar «dos» davant?</b> (comptable).",
  compte:"A <i>un got de llet</i> hi ha dos noms: <b>got</b> és comptable (és el nom de mesura) i <b>llet</b> és el no comptable. I <i>ramat</i> és col·lectiu encara que vagi en singular.",
  fc:[["Les quatre parelles de classes de noms","Comuns/propis, concrets/abstractes, individuals/col·lectius, comptables/no comptables."],["Què és un antropònim?","Un nom propi de persona (Paula)."],["Què és un topònim?","Un nom propi de lloc (Menorca, Maó)."],["Un nom abstracte designa…","Una realitat no material: veritat, valentia, calma."],["Col·lectiu de pi, flor i jugador","Pineda, ram i equip."],["Què va davant d'un no comptable?","Quantitatius (poca) o noms de mesura (un quilo de)."]],
  q:[["Quin d'aquests noms és propi?",["ciutat","Menorca","illa"],1,"Menorca és un lloc únic: un topònim."],
     ["Com es diuen els noms propis de lloc?",["Antropònims","Topònims","Col·lectius"],1,"Els de persona són antropònims; els de lloc, topònims."],
     ["Quin d'aquests noms és abstracte?",["valentia","pescador","rosa"],0,"La valentia no es pot tocar: és una qualitat."],
     ["Què designa un nom col·lectiu en singular?",["Un sol element","Un conjunt d'elements","Una cosa que no es pot tocar"],1,"gent, alumnat, ramat."],
     ["Quin és el col·lectiu de «pi»?",["pineda","ram","aviram"],0,"Ram és de flors i aviram, d'ocells."],
     ["Quin d'aquests noms és no comptable?",["pastís","farina","rosa"],1,"No pots dir «dues farines»."],
     ["Què pot portar davant un nom no comptable?",["Només un numeral, com a «dues farines», igual que els comptables","Quantitatius i noms de mesura, com «un quilo de farina»","Res: sempre va sol"],1,"poca farina, un quilo de farina, un raig d'oli."],
     ["A «un got de llet», quin nom és el no comptable?",["got","llet","un"],1,"Got és el nom de mesura (comptable)."],
     ["«Ramat» és un nom…",["comú, concret, col·lectiu i comptable","propi, abstracte, individual i no comptable","comú, abstracte, individual i comptable"],0,"Un mateix nom porta quatre etiquetes."],
     ["«Ovella» és un nom individual o col·lectiu?",["Col·lectiu, perquè n'hi ha moltes","Individual: designa un sol element","Totes dues coses alhora"],1,"Ovella és individual; ramat és col·lectiu."]]},
 {id:"genere",ic:"👫",col:"#db2777",titol:"Les marques de gènere i de nombre",font:"Llibre · Gramàtica 1.3 · pàg. 48-49",
  idea:"L'article ens diu de quin gènere és un nom, i els noms de persones i d'animals canvien de forma amb unes marques que es diuen morfemes flexius.",
  pts:["La majoria dels noms tenen un <b>gènere assignat</b>. La <b>forma de l'article</b> diu si és <b>masculí (m.)</b> o <b>femení (f.)</b>: <i>un costum</i> (m.), <i>els senyals</i> (m.), <i>una dent</i> (f.), <i>les postres</i> (f.).",
   "Els noms de <b>persones o animals</b> canvien de forma amb marques de <b>gènere</b> i de <b>nombre</b>: els <b>morfemes flexius</b>. <i>nebot, neboda, nebots, nebodes</i> · <i>gall, gallina, galls, gallines</i> · <i>actor, actriu, actors, actrius</i>.",
   "De vegades la terminació canvia una mica per sonar bé: <i>amic → amigues</i>, <i>psicòleg → psicòlogues</i>.",
   "Les <b>professions</b> solen tenir dues formes: <i>l'àrbitre / l'àrbitra, el ministre / la ministra, el mosso / la mossa</i>.",
   "Alguns noms fan servir <b>paraules diferents</b>: <i>l'amo / la mestressa, l'oncle / la tia, el padrastre / la madrastra, el gendre / la jove o la nora, el cavall / l'euga, l'ase o el ruc / la somera, el boc / la cabra, el porc / la truja o la verra, el marrà / l'ovella</i>.",
   "Alguns animals tenen <b>una sola forma</b>: s'hi afegeix <b>mascle</b> o <b>femella</b> (és una aposició): <i>un rossinyol mascle / un rossinyol femella</i>."],
  truc:"L'<b>article és el xivato del gènere</b>: <i>un / el</i> → masculí; <i>una / la</i> → femení. Si dubtes, mira el diccionari: l'abreviatura <b>m.</b> o <b>f.</b> et diu quin article li toca.",
  compte:"En català: <b>el costum</b>, <b>la dent</b>, <b>les postres</b> (en castellà van al revés). I el femení de cavall és <b>l'euga</b>, no «cavalla».",
  fc:[["Què ens diu el gènere d'un nom?","L'article: un/el, masculí; una/la, femení."],["Com es diuen les marques de gènere i de nombre?","Morfemes flexius."],["Femení de cavall","L'euga."],["Femení de gendre","La jove o la nora."],["Femení i plurals de psicòleg","Psicòloga, psicòlegs, psicòlogues."],["Com dius que un rossinyol és femella?","Un rossinyol femella."]],
  q:[["Com es diu en català?",["el costum","la costum","Totes dues formes són correctes"],0,"En català és masculí: el costum."],
     ["Com es diu en català?",["la dent","el dent","Totes dues formes són correctes"],0,"En català és femení: la dent."],
     ["Quin és el femení de «cavall»?",["la cavalla","l'euga","la somera"],1,"Somera és la femella de l'ase."],
     ["Com es diuen les marques que fan canviar de forma els noms de persones i animals?",["Morfemes flexius","Topònims","Especificadors"],0,"Marquen el gènere i el nombre: nebot, neboda, nebots, nebodes."],
     ["Quin és el femení plural de «psicòleg»?",["psicòlegues","psicòlogues","psicòlegs"],1,"La terminació canvia per sonar bé, com amic → amigues."],
     ["Quin és el femení de «actor»?",["actora","actriu","actoressa"],1,"actor, actriu, actors, actrius."],
     ["El rossinyol té una sola forma. Com dius que és femella?",["una rossinyola","un rossinyol femella","la rossinyol"],1,"S'hi afegeix mascle o femella."],
     ["Quina parella fa servir paraules diferents per a cada gènere?",["l'oncle / la tia","el nebot / la neboda","el gall / la gallina"],0,"Les altres canvien la terminació."],
     ["Quin és el femení de «gendre»?",["la gendra","la jove o la nora","la madrastra"],1,"Madrastra és el femení de padrastre."],
     ["Com es diu en català?",["les postres","els postres","el postre"],0,"En català és femení i plural: les postres."]]},
 {id:"invariables",ic:"🔒",col:"#0284c7",titol:"Els noms invariables",font:"Llibre · Gramàtica 1.4 · pàg. 50",
  idea:"Alguns noms no canvien: uns tenen la mateixa forma en masculí i en femení (només canvia l'article) i uns altres, la mateixa forma en singular i en plural.",
  pts:["<b>Invariables en gènere</b>: <i>un / una cantant, periodista, captaire, conserge, pilot, gimnasta</i>. Només canvia l'article.",
   "Professions amb <b>una sola forma</b>: <i>conferenciant, fisioterapeuta, fiscal, intèrpret, lampista, vigilant, xef</i>.",
   "<b>Invariables en nombre</b>: <i>un / els llapis, focus, globus, tipus, dilluns, temps</i>.",
   "Noms que <b>només fem servir en plural</b>: <i>les alicates, les calces, els calçotets, les escombraries, les estenalles, les estisores, les pinces, les postres, les setrilleres, els sostenidors</i>.",
   "<b>-u o -us?</b> Si el singular acaba en <b>-u</b>, hi afegim -s: <i>una tribu → les tribus, un ritu → els ritus, un individu → els individus, un residu → els residus</i>.",
   "Si el singular ja acaba en <b>-us</b>, el plural és igual: <i>un fetus → els fetus, un focus → els focus, un virus → els virus, un globus → els globus</i>.",
   "💡 <i>Sabies que…?</i> <i>Dilluns</i> ve del llatí <i>dies Lunae</i>, «el dia de la Lluna»: per això ja porta la essa."],
  truc:"Els invariables de nombre <b>ja porten la essa de casa</b> (<i>llapis, focus, dilluns, temps</i>): en plural no hi afegeixis res. Els invariables de gènere deixen <b>tota la feina a l'article</b>: <i>el / la cantant, el / la pilot</i>.",
  compte:"Res de «llapissos», «virussos» ni «viros»: <b>dos llapis, dos virus</b>. En canvi, <i>tribu</i> i <i>ritu</i> acaben en -u i fan <b>tribus, ritus</b>.",
  fc:[["Plural de llapis","Llapis (igual)."],["Plural de virus","Virus (igual)."],["Plural de tribu","Tribus."],["Un nom invariable en gènere","Cantant, periodista, pilot… (només canvia l'article)."],["Tres noms que només fem servir en plural","Les estisores, les alicates, les postres…"],["Tres professions amb una sola forma","Fisioterapeuta, intèrpret, xef…"]],
  q:[["Quin és el plural de «llapis»?",["llapissos","llapis","llapisos"],1,"Ja porta la essa de casa."],
     ["Quin és el plural de «virus»?",["els virussos","els viros","els virus"],2,"Si acaba en -us, el plural és igual."],
     ["Quin és el plural de «tribu»?",["les tribus","les tribu","les tribues"],0,"Acaba en -u: hi afegim -s."],
     ["Quin d'aquests noms és invariable en gènere?",["cantant","actor","nebot"],0,"el cantant / la cantant: només canvia l'article."],
     ["Quin d'aquests noms només el fem servir en plural?",["estisores","llapis","dilluns"],0,"Diem les estisores, mai «l'estisora»."],
     ["Per què «focus» no canvia en plural?",["Perquè el singular ja acaba en -us","Perquè és un nom col·lectiu","Perquè és un nom abstracte"],0,"un focus → els focus."],
     ["Quina d'aquestes professions té una sola forma per als dos gèneres?",["fisioterapeuta","àrbitre","ministre"],0,"Àrbitre i ministre fan àrbitra i ministra."],
     ["A «el pilot / la pilot», què ens diu el gènere?",["La terminació del nom","Només l'article","La paraula mascle o femella"],1,"Els invariables de gènere deixen tota la feina a l'article."],
     ["Quin és el plural de «un ritu»?",["els ritu","els ritus","els rituts"],1,"Ritu acaba en -u: fa ritus."]]},
 {id:"clau",ic:"🔑",col:"#ca8a04",titol:"Noms iguals amb gènere i significat diferents",font:"Llibre · Gramàtica 1.5 · pàg. 50-51",
  idea:"Alguns noms s'escriuen igual però volen dir coses diferents si són masculins o femenins: el clau i la clau, el pols i la pols, el son i la son.",
  pts:["<b>el clau</b>: tija de ferro · <b>la clau</b>: peça que activa un pany.",
   "<b>el pols</b>: batec del cor · <b>la pols</b>: partícules diminutes.",
   "<b>el son</b>: acte de dormir · <b>la son</b>: ganes de dormir.",
   "Aquí l'article canvia el significat sencer. A la ferreteria, «el clau» és una peça de ferro per clavar; «la clau» és una còpia de la de casa.",
   "La forma femenina d'alguns noms designa un objecte <b>semblant però més gran</b>: <i>una plata de panellets / un plat d'amanida</i>.",
   "També pot designar un <b>ús diferent</b>: <i>una gerra de suc / un gerro de flors</i>.",
   "Més parelles de la pàg. 51 (els significats els afegeix el resum): <i>el llum</i> (l'aparell que fa llum) / <i>la llum</i> (la claror) · <i>el fi</i> (la finalitat) / <i>la fi</i> (el final) · <i>el pudor</i> (la vergonya) / <i>la pudor</i> (la mala olor)."],
  truc:"El clau es <b>clava</b>, la clau <b>obre</b>. El pols <b>batega</b>, la pols <b>s'escombra</b>. El son és <b>dormir</b>; la son és <b>tenir-ne ganes</b> (i et fa badallar).",
  compte:"No són el mateix nom amb un altre article: són <b>dues paraules diferents</b>. Si canvies l'article, canvies el significat.",
  fc:[["el clau / la clau","Tija de ferro / peça que activa un pany."],["el pols / la pols","Batec del cor / partícules diminutes."],["el son / la son","Acte de dormir / ganes de dormir."],["una plata / un plat","La plata és semblant però més gran."],["una gerra / un gerro","Ús diferent: gerra de suc, gerro de flors."]],
  q:[["Què és «el clau»?",["Una tija de ferro per clavar","Una peça que activa un pany","El batec del cor"],0,"El clau es clava; la clau obre."],
     ["Què és «la pols»?",["El batec del cor","Partícules diminutes","Les ganes de dormir"],1,"La pols s'escombra; el pols batega."],
     ["«Tinc molta son.» Què vol dir aquí «son»?",["L'acte de dormir","Ganes de dormir","Un somni"],1,"La son són les ganes de dormir."],
     ["Què vol dir «el son»?",["L'acte de dormir","Les ganes de dormir","Un soroll molt fort"],0,"El son és dormir; la son, tenir-ne ganes."],
     ["El metge et pren… per saber com batega el cor.",["la pols","el pols","les pols"],1,"El pols és el batec del cor."],
     ["Quina diferència hi ha entre «una plata» i «un plat»?",["La plata és un objecte semblant però més gran","Són exactament el mateix objecte","El plat és més gran que la plata"],0,"Una plata de panellets, un plat d'amanida."],
     ["«Un gerro de flors» i «una gerra de suc»: què canvia?",["Res, són sinònims","L'ús: un és per a flors i l'altre per a beure","Només la mida"],1,"El femení pot designar un ús diferent."],
     ["Per obrir la porta de casa necessites…",["la clau","el clau","el pols"],0,"La clau activa el pany."],
     ["En aquests noms, què canvia el significat?",["El gènere: masculí o femení","El nombre: singular o plural","L'accent"],0,"Mateixa paraula, gènere diferent, significat diferent."]]},
 {id:"punts",ic:"🛑",col:"#dc2626",titol:"El punt, l'interrogant, l'admiració i els punts suspensius",font:"Llibre · Ortografia 1 · pàg. 54",
  idea:"Cada signe de puntuació té la seva feina. El punt, l'interrogant, l'admiració i els punts suspensius tanquen l'oració, i darrere seu va majúscula.",
  pts:["<b>Punt final</b>: marca l'acabament d'un text. <b>No</b> es posa al final d'un títol o d'un subtítol.",
   "<b>Punt i a part</b>: marca el final d'un paràgraf. A la ratlla següent es deixa el <b>sagnat</b>, un queixal en blanc de tres o quatre espais.",
   "<b>Punt i seguit</b>: marca l'acabament d'una oració que no està enllaçada amb cap altra: <i>Va sonar el timbre. Tothom va sortir corrents.</i>",
   "<b>Interrogant</b> (?): marca l'entonació de les oracions <b>interrogatives</b>. <b>Admiració</b> (!): marca l'entonació de les <b>exclamatives</b>.",
   "<b>Punts suspensius</b> (…): una oració <b>no acabada</b> (<i>Si no t'afanyes… Ja ho veuràs.</i>) o una <b>enumeració</b> que no queda tancada. A les enumeracions també es pot posar <b>etc.</b>, però mai les dues coses alhora.",
   "Darrere el punt, i darrere ? ! … quan acaben l'oració, va <b>MAJÚSCULA</b>.",
   "💡 <i>Sabies que…?</i> En català, l'interrogant i l'admiració d'obrir (¿ ¡) no són obligatoris, però es poden posar quan la frase és llarga."],
  truc:"<b>Porta tancada.</b> Els signes que tanquen l'oració (<b>. ? ! …</b>) demanen <b>MAJÚSCULA</b> darrere.",
  compte:"Els <b>títols no porten punt</b> final. I <b>etc.</b> i els punts suspensius no van mai junts: <i>Hèctor, Helena, etc.</i>, i no pas <i>Helena, etc…</i>",
  fc:[["Quins són els tres tipus de punt?","Punt final, punt i a part i punt i seguit."],["Què és el sagnat?","L'espai en blanc de 3 o 4 espais al començament d'un paràgraf."],["Porten punt final els títols?","No."],["Per a què serveixen els punts suspensius?","Per a una oració no acabada o una enumeració no tancada."],["Què va darrere d'un interrogant que acaba l'oració?","Majúscula."],["Etc. i punts suspensius junts?","Mai: o l'un o l'altre."]],
  q:[["Quin punt marca el final d'un paràgraf?",["El punt final","El punt i a part","El punt i seguit"],1,"Després, a la ratlla nova, es deixa el sagnat."],
     ["Què és el sagnat?",["L'espai en blanc a l'inici d'un paràgraf","El punt que va al final del títol","La ratlla que separa dos paràgrafs"],0,"Un queixal en blanc de tres o quatre espais."],
     ["On NO es posa mai punt final?",["Al final d'un text","Al final d'un títol","Al final d'un conte"],1,"Els títols no porten punt."],
     ["«Va sonar el timbre. Tothom va sortir corrents.» Quin punt hi ha entre les dues oracions?",["Punt i seguit","Punt i a part","Punt final"],0,"El text continua a la mateixa ratlla."],
     ["Darrere un interrogant que acaba l'oració, com comença la paraula següent?",["Amb minúscula","Amb majúscula","Amb minúscula i entre cometes"],1,"? acaba l'oració: porta tancada, majúscula."],
     ["Per a què serveixen els punts suspensius?",["Per a una oració no acabada o una enumeració no tancada","Per acabar un text i deixar clar que ja no hi ha res més","Per fer una pregunta"],0,"Si no t'afanyes… Ja ho veuràs."],
     ["Quina d'aquestes enumeracions està ben escrita?",["Porto llapis, gomes, retoladors, etc.","Porto llapis, gomes, retoladors, etc…","Porto llapis, gomes, retoladors etc"],0,"Etc. o punts suspensius, mai les dues coses."],
     ["Quin signe marca l'entonació de les oracions exclamatives?",["L'interrogant","L'admiració","El punt i coma"],1,"Quin gol més bonic!"],
     ["«Quin gol més bonic! Ha estat increïble.» Per què «Ha» comença amb majúscula?",["Perquè l'admiració tanca l'oració","Perquè és un verb","Perquè els verbs sempre comencen amb majúscula"],0,"L'admiració acaba l'oració: darrere, majúscula."]]},
 {id:"puntcoma",ic:"🎬",col:"#9333ea",titol:"El punt i coma i els dos punts",font:"Llibre · Ortografia 1 · pàg. 54-55",
  idea:"El punt i coma i els dos punts deixen l'oració entreoberta: darrere seu va minúscula, llevat de les paraules d'algú entre cometes.",
  pts:["<b>Punt i coma</b> (;): a) separa <b>dues oracions</b> que tenen una relació de proximitat: <i>A l'estiu anem a la platja; a l'hivern, a la neu.</i> b) separa <b>sèries llargues</b> i complexes (davant de la <i>i</i> final es posa una coma).",
   "<b>Dos punts</b> (:): a) separen dues oracions relacionades, en què la segona depèn de la primera: <i>No vaig poder venir: estava malalt.</i>",
   "b) Introdueixen una <b>enumeració</b> o un <b>exemple</b>: <i>Hi ha quatre gèneres: poesia, narrativa, teatre i assaig.</i>",
   "c) Introdueixen les <b>paraules d'una altra persona</b>: <i>La mestra va dir: «Demà hi ha examen».</i>",
   "Darrere el punt i coma i els dos punts va <b>minúscula</b>. Però si els dos punts introdueixen les paraules exactes d'algú, van amb <b>majúscula</b> i entre <b>cometes «»</b>.",
   "Resum: <b>. ? ! …</b> (si acaben l'oració) → MAJÚSCULA · <b>; :</b> → minúscula."],
  truc:"<b>Porta tancada, porta entreoberta.</b> El <b>;</b> i els <b>:</b> deixen la porta entreoberta: minúscula. I els dos punts són un <b>teló que s'obre</b>: darrere hi ha una explicació, una llista o la veu d'algú.",
  compte:"Darrere el punt i coma <b>no</b> va majúscula. Només les paraules d'algú, després dels dos punts, comencen amb majúscula i entre cometes.",
  fc:[["Què va darrere el punt i coma?","Minúscula."],["Per a què serveix el punt i coma?","Per separar dues oracions molt relacionades o sèries llargues."],["Tres usos dels dos punts","Una explicació, una enumeració o exemple, i les paraules d'algú."],["Dos punts + paraules d'algú","Majúscula i entre cometes «»."],["Porta tancada o entreoberta: ; i :","Entreoberta: minúscula."]],
  q:[["Darrere el punt i coma, com comença la paraula següent?",["Amb minúscula","Amb majúscula","Amb majúscula i entre cometes"],0,"El ; deixa la porta entreoberta."],
     ["«Hi ha quatre gèneres ▢ poesia, narrativa, teatre i assaig.» Quin signe hi va?",["Dos punts (:)","Punt i coma (;)","Punts suspensius (…)"],0,"Els dos punts introdueixen una enumeració."],
     ["«A l'estiu anem a la platja ▢ a l'hivern, a la neu.» Quin signe hi va, com a l'exemple del llibre?",["Dos punts (:)","Punt i coma (;)","Interrogant (?)"],1,"Separa dues oracions amb relació de proximitat."],
     ["Què poden introduir els dos punts?",["Una explicació, una enumeració o les paraules d'algú","Només el final d'un text, com fa el punt final quan s'acaba","Només una pregunta"],0,"Són un teló que s'obre."],
     ["La mestra va dir ▢ «Demà hi ha examen». Quin signe va davant de les cometes?",["Dos punts","Punt i coma","Punt i seguit"],0,"Els dos punts introdueixen les paraules d'una altra persona."],
     ["Quan els dos punts introdueixen les paraules exactes d'una altra persona…",["van amb majúscula i entre cometes «»","van amb minúscula i sense cometes","s'hi posen punts suspensius"],0,"La mestra va dir: «Demà hi ha examen»."],
     ["Per a què serveix el punt i coma?",["Per separar dues oracions molt relacionades o sèries llargues","Per acabar un text","Per tancar l'oració i començar la següent sempre amb majúscula"],0,"A l'estiu anem a la platja; a l'hivern, a la neu."],
     ["Quins signes deixen la «porta entreoberta», amb minúscula darrere?",["El punt i coma i els dos punts","El punt i l'interrogant","L'admiració i els punts suspensius"],0,"Els que tanquen l'oració (. ? ! …) demanen majúscula."],
     ["Darrere de quin d'aquests signes va minúscula?",["Els dos punts que introdueixen una llista","El punt i seguit","L'interrogant que acaba l'oració"],0,"Darrere el punt i l'interrogant que acaba l'oració va majúscula."]]}
];
const OB=[
 {t:"La literatura: l'art de la paraula",q:"Què és la literatura? Fes servir aquestes paraules: <b>art</b>, <b>creativa</b> i <b>llenguatge estètic</b>. Digues també quin és el seu objectiu i posa l'exemple de Maria Dolors Alibés.",p:["L'art de dir coses / l'art de la paraula","De manera creativa","Amb un llenguatge estètic (bonic)","Objectiu: emocionar i agradar","Exemple: els records són roses que punxen"],
  m:"La literatura és l'art de dir les coses de manera creativa, amb un llenguatge estètic, és a dir, bonic. Vol emocionar i agradar. Per exemple, Maria Dolors Alibés no diu que els records fan mal: diu que són roses que tenen espines."},
 {t:"La literatura oral tradicional",q:"Com es van conservar els textos literaris quan encara no hi havia escriptura? Per què els primers humans feien servir la literatura quan cantaven i explicaven històries?",p:["Es transmetien de viva veu (oral)","Es guardaven a la memòria","Passaven de pares a fills i als néts","Per fer les històries més emocionants","Així es va formar la literatura oral tradicional"],
  m:"Es van conservar a la memòria. Les històries i les cançons es transmetien de viva veu: els pares les explicaven als fills, i els fills als néts. Feien servir la literatura per fer-les més emocionants. Així va néixer la literatura oral tradicional."},
 {t:"La literatura escrita",q:"Explica tres diferències entre la literatura oral tradicional i la literatura escrita: com es transmet cadascuna, qui n'és l'autor i quantes versions té el text. Acaba dient quin invent va fer possible la literatura escrita.",p:["Transmissió: l'oral de viva veu (un orador recita); l'escrita per escrit (copistes, manuscrits)","Autor: l'oral és anònima; l'escrita és d'un autor concret","Versions: l'oral té diverses versions; l'escrita una versió única","L'invent: l'alfabet, que va portar l'escriptura"],
  m:"La literatura oral es transmet de viva veu: un orador recita i els altres escolten. L'escrita es transmet en llibres, i abans de la impremta els copistes els copiaven a mà. L'oral és anònima, no sabem qui la va fer; l'escrita és d'un autor que surt a la portada. L'oral té diverses versions, perquè cada orador la canvia una mica, i l'escrita té una versió única. La literatura escrita va ser possible gràcies a la invenció de l'alfabet."},
 {t:"La literatura escrita",q:"Què va provocar la invenció de l'alfabet? Explica què va passar amb el text de les obres, amb els autors i amb l'artista que recitava i el grup que l'escoltava.",p:["Va portar l'escriptura","El text va quedar fixat (versió única)","Les obres van tenir un autor amb nom","L'escriptor solitari va arraconar l'artista que recitava","El lector solitari i silenciós va relegar el grup d'oients"],
  m:"La invenció de l'alfabet va portar l'escriptura. El text va quedar fixat, amb una sola versió, i les obres van tenir un autor amb nom. L'escriptor solitari i reflexiu va anar arraconant l'artista que recitava, i la persona que llegeix sola i en silenci va anar relegant el grup que escoltava."},
 {t:"Els gèneres literaris: vers i prosa",q:"Digues els quatre gèneres literaris i, de cadascun, si s'escriu en vers, en prosa o en diàlegs, i què fa.",p:["Poesia: en vers; expressa sentiments, reflexions o fets","Narrativa: en prosa; un narrador explica uns fets","Teatre: en diàlegs; un conflicte humà per representar","Assaig: en prosa; l'autor dona reflexions i opinions"],
  m:"Hi ha quatre gèneres. La poesia s'escriu en vers i expressa sentiments, reflexions o fets. La narrativa va en prosa i un narrador explica uns fets reals o imaginaris. El teatre va en diàlegs i explica un conflicte humà per representar-lo en un escenari. I l'assaig va en prosa i l'autor hi diu les seves reflexions i opinions."},
 {t:"Els gèneres literaris: vers i prosa",q:"Explica la diferència entre un text en vers i un text en prosa. Què és un vers i què és una estrofa?",p:["Vers: segueix regles mètriques","Regles: estrofes, síl·labes, ritme i rima","Prosa: forma habitual del llenguatge, sense regles mètriques","Vers = cada ratlla; estrofa = grup de versos"],
  m:"Un text en vers segueix unes regles mètriques: té estrofes, les síl·labes es compten, té ritme i sovint rima. La prosa és la manera normal d'escriure, sense regles mètriques, i les línies arriben fins al final de la ratlla. Un vers és cada ratlla d'un poema i una estrofa és un grup de versos."},
 {t:"El teatre, l'assaig i com reconèixer els gèneres",q:"Quina diferència hi ha entre la poesia lírica i l'èpica? I com acaben la tragèdia, la comèdia i el drama?",p:["Lírica: el poeta expressa un sentiment intens o una reflexió","Èpica: una història llegendària d'uns herois","Tragèdia: desenllaç fatal","Comèdia: desenllaç feliç","Drama: desenllaç incert"],
  m:"A la poesia lírica el poeta expressa un sentiment intens o una reflexió profunda. A l'èpica explica una història llegendària d'uns herois. Al teatre, la tragèdia és seriosa i acaba amb un desenllaç fatal, la comèdia és graciosa i acaba bé, amb un desenllaç feliç, i el drama és realista i té un desenllaç incert."},
 {t:"El nom i el sintagma nominal",q:"Què pot designar un nom? Posa un exemple de cada una de les cinc coses. Explica també per què diem que és una paraula variable.",p:["Persona (Harry) i animal (mussol)","Planta (menta) i objecte (carta)","Idea (amistat)","Variable: canvia de gènere i de nombre (noi, noia, nois, noies)"],
  m:"Un nom pot designar una persona, com Harry; un animal, com mussol; una planta, com menta; un objecte, com carta; o una idea, com amistat. És variable perquè canvia de gènere i de nombre: noi, noia, nois, noies."},
 {t:"El nom i el sintagma nominal",q:"Analitza el sintagma nominal <i>la meva motxilla nova</i>: quin és l'especificador, quin el nucli i quin el complement? Explica què fa cada peça i com trobes el nucli.",p:["Especificador: la meva (presenta el nom)","Nucli: motxilla (el nom)","Complement: nova (dona detalls)","El nucli: si el trec, ja no sé de què parlo"],
  m:"L'especificador és «la meva», que va davant i presenta el nom. El nucli és «motxilla», que és el nom. El complement és «nova», que va darrere i dona un detall. El nucli el trobo pensant quina paraula, si la trec, ja no sé de què parlo."},
 {t:"Les classes de noms",q:"Explica la diferència entre: a) un nom individual i un de col·lectiu; b) un nom comptable i un de no comptable. Posa un exemple de cada classe. Acaba dient quines paraules pot portar al davant un nom no comptable, amb un exemple.",p:["Individual: en singular, un sol element (ovella)","Col·lectiu: en singular, un conjunt (ramat)","Comptable: es pot comptar, admet un numeral (dos pastissos)","No comptable: no es compta per unitats (farina)","Davant del no comptable: quantitatius o noms de mesura (poca farina, un quilo de farina)"],
  m:"Un nom individual, en singular, vol dir una sola cosa, com ovella. Un col·lectiu, en singular, vol dir un grup, com ramat. Un nom comptable es pot comptar i hi puc posar un número davant, com dos pastissos. Un no comptable no es pot comptar per unitats, com farina. Davant d'un no comptable hi poso quantitatius o noms de mesura: poca farina, un quilo de farina."},
 {t:"Les classes de noms",q:"Classifica el nom <i>ramat</i> en les quatre parelles de classes. Després digues de quina classe són <i>Eivissa</i> i <i>valentia</i>, i explica per què.",p:["Ramat: comú i concret","Ramat: col·lectiu i comptable","Eivissa: propi (topònim, nom de lloc)","Valentia: comú i abstracte (no es pot tocar)"],
  m:"Ramat és un nom comú, concret, col·lectiu i comptable: el puc tocar, en singular són moltes ovelles i puc dir dos ramats. Eivissa és un nom propi, un topònim, perquè és el nom d'un lloc. Valentia és comú i abstracte, perquè és una qualitat i no es pot tocar."},
 {t:"Les marques de gènere i de nombre",q:"Escriu el femení singular i els dos plurals de <i>psicòleg</i> i d'<i>actor</i>. Després digues el femení de <i>gendre</i>, de <i>cavall</i> i de <i>porc</i>, i com dius que un rossinyol és femella.",p:["psicòloga, psicòlegs, psicòlogues","actriu, actors, actrius","gendre → la jove o la nora","cavall → l'euga; porc → la truja","un rossinyol femella"],
  m:"Psicòleg fa psicòloga, psicòlegs i psicòlogues. Actor fa actriu, actors i actrius. El femení de gendre és la jove o la nora, el de cavall és l'euga i el de porc és la truja. I si un rossinyol és femella, dic un rossinyol femella."},
 {t:"Els noms invariables",q:"Escriu el plural de <i>una tribu</i>, <i>un virus</i> i <i>un ritu</i>, i explica la regla. Després digues tres professions que tenen una sola forma i tres noms que només fem servir en plural.",p:["les tribus, els virus, els ritus","Si acaba en -us, el plural és igual; si acaba en -u, s'afegeix -s","Professions d'una sola forma (fisioterapeuta, intèrpret, xef…)","Noms només en plural (estisores, alicates, postres…)"],
  m:"Les tribus, els virus i els ritus. Virus ja acaba en -us i el plural és igual; tribu i ritu acaben en -u i hi afegim una -s. Tres professions d'una sola forma són fisioterapeuta, intèrpret i xef. Tres noms que només fem servir en plural són les estisores, les alicates i les postres."},
 {t:"Noms iguals amb gènere i significat diferents",q:"Explica què vol dir <i>el clau</i> i <i>la clau</i>, <i>el pols</i> i <i>la pols</i>, <i>el son</i> i <i>la son</i>. Després inventa't una frase amb <i>el pols</i> i una altra amb <i>la pols</i>.",p:["el clau: tija de ferro / la clau: obre un pany","el pols: batec del cor / la pols: partícules diminutes","el son: acte de dormir / la son: ganes de dormir","Frase correcta amb el pols","Frase correcta amb la pols"],
  m:"El clau és una tija de ferro per clavar i la clau serveix per obrir un pany. El pols és el batec del cor i la pols són partícules molt petites. El son és l'acte de dormir i la son són les ganes de dormir. Frases: «El metge em va prendre el pols.» «Hi ha molta pols damunt de la prestatgeria.»"},
 {t:"El punt i coma i els dos punts",q:"Digues els tres tipus de punt i per a què serveix cadascun. Què és el sagnat? Després explica quan va majúscula i quan minúscula darrere el punt i coma, els dos punts i l'interrogant, i escriu una frase amb dos punts que introdueixin una llista.",p:["Punt final (acaba el text), punt i a part (acaba el paràgraf), punt i seguit (acaba una oració)","Sagnat: espai en blanc a l'inici del paràgraf","Darrere el punt i coma i els dos punts: minúscula","Darrere l'interrogant que acaba l'oració: majúscula","Frase amb dos punts davant d'una llista"],
  m:"El punt final acaba un text, el punt i a part acaba un paràgraf i el punt i seguit acaba una oració i el text continua a la mateixa ratlla. El sagnat és l'espai en blanc al començament d'un paràgraf. Darrere el punt i coma i els dos punts va minúscula, perquè deixen la porta entreoberta; darrere l'interrogant que acaba l'oració va majúscula. Frase: «Necessito tres coses: tovallola, crema i gorra.»"}
];

// 👾 Boss del món (Bona Nota 2.0): nom i monstre del repte final
ASSIG.boss={nom:"El Monstre dels Signes",spr:"monstre"};
